const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID(), KEY='livebeam-demo-v1';
const fresh=()=>({notifications:[],roles:[],schedules:[],logs:[],settings:{serverName:'My community',managerRoles:''}});
let state=fresh(), mode='demo', guild='demo', session=null, metadata={channels:[],roles:[]}, platform='all';
try{state={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'{}')};validateImport(state)}catch{state=fresh()}
const app=$('#app'), modal=$('#modal');
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000)}
async function api(path,options={}){const res=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});if(!res.headers.get('content-type')?.includes('application/json'))throw Error('Live service is not connected. Use demo mode or run the included server.');const json=await res.json();if(!res.ok)throw Error(json.error||'Request failed');return json}
async function save(){if(mode==='live')await api(`/api/guilds/${guild}/config`,{method:'PUT',body:JSON.stringify(state)});else localStorage.setItem(KEY,JSON.stringify(state))}
function log(message){state.logs.unshift({id:uid(),message,time:new Date().toISOString()});state.logs=state.logs.slice(0,100)}
const brand=()=>'<a class="brand" href="/#/"><img src="/logo.svg" alt="">Livebeam</a>';
function nav(){return `<nav class="site-nav" aria-label="Main navigation">${brand()}<div class="nav-links"><a href="/#/pro">Pro</a><a href="/#/docs">Documentation</a><a href="/#/support">Support</a></div><div class="nav-actions"><a class="btn primary small" href="/#/connect">Add to Discord</a><a class="btn secondary small" href="/#/dashboard">Dashboard</a><button class="icon menu-toggle" data-action="menu" aria-label="Show more links" aria-expanded="false">☰</button></div><div class="menu" hidden><a href="/#/">Home</a><a href="/#/dashboard">Dashboard</a><a href="/#/pro">Livebeam Pro</a><a href="/#/docs">Documentation</a><a href="/#/status">System status</a><a href="/#/faq">Frequently asked questions</a></div></nav>`}
function footer(){return `<footer class="footer"><div>${brand()}<div class="social-icons" aria-label="Platforms">◉ Twitch &nbsp; ▷ YouTube &nbsp; K Kick</div><p>© ${new Date().getFullYear()} Livebeam<br>An independent personal project.<br>Not affiliated with Discord, Twitch, YouTube, or Kick.</p><span class="subtle">English (USA)</span></div>${[['Product',['Add to Discord','connect'],['Dashboard','dashboard'],['Livebeam Pro','pro'],['Branding','branding']],['Support',['Help center','docs'],['Commands list','docs/commands'],['Status page','status'],['FAQ','faq']],['Community',['Partners','partners'],['Languages','languages'],['Feedback','support']],['Legal',['Terms of use','terms'],['Privacy policy','privacy']]].map(([title,...links])=>`<div><h4>${title}</h4>${links.map(([text,link])=>`<a href="/#/${link}">${text}</a>`).join('')}</div>`).join('')}</footer>`}
const buttons=()=>'<div class="buttons"><a class="btn primary" href="/#/connect">Add to Discord</a><a class="btn secondary" href="/#/dashboard">Visit Dashboard</a></div>';
const features=list=>`<ul class="feature-list">${list.map(([title,text])=>`<li><span class="check">✓</span><div><strong>${title}</strong><br>${text}</div></li>`).join('')}</ul>`;
function preview(n={}){const name=n.creator||'cozyplayer';const message=(n.message||'{name} is live! Come hang out: {url}').replaceAll('{name}',name).replaceAll('{url}',`https://${n.platform==='youtube'?'youtube.com':n.platform==='kick'?'kick.com':'twitch.tv'}/${name}`).replaceAll('{title}','A new adventure starts here').replaceAll('{game}','Minecraft');return `<div class="discord"><div class="message"><div class="avatar">ϟ</div><div><span class="name">${esc(n.botName||'Livebeam')}</span> <span class="bot-label">✓ APP</span><span class="time">Today at 4:30 PM</span><p>${esc(message)}</p><div class="embed" style="border-left-color:${/^#[0-9a-f]{6}$/i.test(n.color)?n.color:'#9146ff'}"><strong>${esc(name)}</strong><p class="embed-title">A new adventure starts here</p><p>Playing Minecraft · Live now</p><div class="stream-art"><span>THE NEXT ADVENTURE</span></div><p>Watch on ${esc(n.platform||'Twitch')} ↗</p></div></div></div></div>`}
function home(){return `<div class="hero-wrap">${nav()}<main id="main" class="hero"><div class="hero-inner"><h1>Build your streaming community on Discord.</h1><p>Bring your Twitch, YouTube, and Kick community together with Livebeam.</p>${buttons()}</div></main></div><section class="section"><div><div class="eyebrow">Stream Notifications</div><h2>Every stream. Every video.<br>All in your Discord.</h2><p>Give your community a place to tune in. Set up announcements for your favorite creators and make every go-live moment feel like an event.</p>${features([['Make it your own.','Personalize messages, colors, thumbnails, and cooldowns.'],['Keep notifications relevant.','Choose which games and title keywords trigger an announcement.'],['Take care of the details.','Crosspost announcements and choose what happens when a stream ends.']])}<a class="guide" href="/#/docs/notifications">Set up stream notifications →</a><a class="guide" href="/#/docs/youtube">Connect a YouTube channel →</a></div><div class="mock"><span class="spark">✦</span>${preview()}<div class="floating">◉ cozyplayer <small>Streaming Minecraft</small></div></div></section><div class="tinted"><section class="section reverse"><div class="mock"><div class="roles-preview"><div><div class="eyebrow">YOUR COMMUNITY</div><h3>In the spotlight.</h3><div class="role-member"><div class="avatar">c</div><div>cozyplayer<br><small class="subtle">Streaming Minecraft</small></div></div><span class="role-badge">● Live on Twitch</span></div><div class="role-sidebar"><h4>LIVE NOW — 2</h4><div class="role-member"><span class="status-dot"></span>cozyplayer</div><div class="role-member"><span class="status-dot"></span>moonlight</div><h4>ONLINE — 24</h4><div class="role-member">✦ Alex</div><div class="role-member">✦ Sky</div></div></div></div><div><div class="eyebrow">Live Role</div><h2>Put your creators<br>in the spotlight</h2><p>Help members find the people streaming right now. Assign a special Discord role when a connected Twitch creator goes live, then remove it when they finish.</p>${features([['You set the rules.','Include or exclude members using role filters.'],['Make an entrance.','Pair live roles with a community announcement.'],['Recognize your creators.','Organize connected members with role configurations.']])}<a class="guide" href="/#/docs/roles">Set up Live Role →</a></div></section></div><section class="section"><div><div class="eyebrow">Livebeam Pro</div><h2>More possibilities for<br>your community</h2><p>Give your server room to grow with advanced configuration and a shared calendar for upcoming streams.</p>${features([['Bring your schedule along.','Create Discord events from upcoming Twitch streams.'],['Fine-tune every announcement.','Customize your notification style and stream-end behavior.'],['Make room for more creators.','Manage multiple live role rules and additional channels.']])}<a class="guide" href="/#/pro">Explore Livebeam Pro →</a></div><div class="calendar-preview"><h3>▦ Community events</h3><div class="calendar-grid">${['M','T','W','T','F','S','S',...Array.from({length:28},(_,i)=>i+1)].map((d,i)=>`<span class="${[11,16,23,28].includes(i)?'event-day':''}">${d}</span>`).join('')}</div><div class="event-preview"><small>● STARTING SOON</small>Community game night<br><p>Join cozyplayer for a new adventure.</p></div></div></section><section class="cta"><h2>Your next great stream starts with a community.</h2><p>Bring yours together with Livebeam.</p>${buttons()}</section>${footer()}`}
const planRows=[['Twitch notifications','5','250'],['YouTube channels','5','10'],['Kick channels','5','10'],['Custom message and embed color','✓','✓'],['Game and title filters','—','5 rules'],['Custom thumbnails and bot identity','—','✓'],['Stream cleanup and cooldowns','—','✓'],['Automatic crossposting','—','✓'],['Live Role configurations','1','5'],['Role filter modes','Include','Include / exclude'],['Twitch schedule sync','—','✓'],['Server manager roles','—','✓']];
function pro(){return `${nav()}<main id="main"><header class="page-head"><h1>Give your community more with Pro.</h1><p>A bigger toolkit for your next chapter.</p><a class="btn secondary" href="/#/dashboard">Explore the dashboard</a></header><div class="content"><div class="notice">Personal project edition: all configuration tools are available. Paid subscriptions are not enabled and no payment is collected.</div><div class="price-grid" style="margin-top:28px"><article class="price-card"><div class="eyebrow">THE ESSENTIALS</div><h2>Always free</h2><p class="subtle">Bring your community together.</p><div class="price">$0<span> / month</span></div><a class="btn outline" href="/#/connect">Get started</a></article><article class="price-card featured"><div class="eyebrow">MORE ROOM TO GROW</div><h2>Livebeam Pro</h2><p class="subtle">All the tools, with more flexibility.</p><div class="price">Included<span> in the personal edition</span></div><a class="btn purple" href="/#/dashboard">Try every feature</a></article></div><table class="comparison"><thead><tr><th>Compare features</th><th>Free profile</th><th>Pro profile</th></tr></thead><tbody>${planRows.map(r=>`<tr>${r.map((v,i)=>`<${i?'td':'th'}>${v}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div></main>${footer()}`}
const articles={
about:['Welcome to Livebeam','Livebeam brings stream announcements, role rules, and a streaming calendar into one place.','Getting started','Open the dashboard to try the demo. Demo settings stay in this browser and do not send messages. To connect a real server, run the included Node service with your own Discord application credentials, then choose Connect Discord.'],
notifications:['Stream notifications','Create a notification for each creator and choose the Discord channel where it should appear.','Create your first notification','Select Add notification. Pick Twitch, YouTube, or Kick and enter the creator identifier. Twitch uses a login; YouTube uses a UC channel ID; Kick uses a numeric broadcaster ID. Choose a destination, customize the message, and save. Game and title filters are case-insensitive and all populated filters must match. Cooldowns are in minutes.'],
youtube:['YouTube notifications','Announce new uploads and livestreams from your favorite channels.','Channel setup','Use the UC-prefixed channel ID from YouTube, not an @handle. The live service requires YOUTUBE_API_KEY. Select uploads, livestreams, or both. New upload polling uses the uploads playlist; livestream polling uses search and consumes more quota. Shorts are not classified separately in this version.'],
variables:['Message variables','Write one message and let Livebeam fill in the stream details.','Available variables','Use {name} for the creator, {title} for the stream title, {game} for the category, and {url} for the viewing link. The editor includes a preview. Mentions are disabled by default on the live service to prevent accidental mass notifications.'],
filters:['Filters and cleanup','Choose when an announcement appears and what happens afterward.','Stream lifecycle','Separate game names with commas; any listed game matches. Separate title keywords with commas; every keyword must appear. A cooldown limits repeated notifications. Cleanup can keep, edit, or delete the original announcement, or send an ending message. These lifecycle options apply to livestreams.'],
roles:['Live Role','Highlight connected Twitch creators while they are live.','Set up a rule','Choose a Discord role, then add member mappings in the form DiscordUserID:twitchlogin, one per line. Optionally enter Discord role IDs to include or exclude. The bot needs Manage Roles and must be placed above the role it assigns. This implementation uses explicit mappings; it does not inspect Discord streaming presence or verify Twitch affiliate status.'],
schedules:['Stream schedules','Bring upcoming Twitch streams to your Discord events list.','Create a schedule sync','Add a Twitch login, event title, and description. On the live service, the poller creates upcoming external Discord events and updates changed events. The bot needs Create Events and Manage Events. Demo mode saves configurations only.'],
connections:['Account connections','Use your own Discord application to connect Livebeam to a server.','Credentials and access','Copy .env.example to .env and fill in the application credentials. Register PUBLIC_URL/auth/discord/callback as the Discord OAuth redirect. Tokens stay on the server. Only the server owner, administrators, users with Manage Server, or configured manager roles can edit settings. Demo data is kept separately from live server data.'],
commands:['Commands','Livebeam is configured through its web dashboard.','Current interface','Notification editing, Live Role rules, schedules, diagnostics, and data export are available from the dashboard. Discord slash commands, native Linked Roles, subscriptions, and a support-ticket bot are not implemented in this personal edition.'],
privacy:['Your data','You control your saved configuration.','Export or remove data','Use Settings to download your configuration as JSON. Demo reset removes only this browser’s demo data. Live configurations are stored in the data directory of your deployment; back it up and protect it. Logging out removes the session cookie.']};
function docs(key='about'){let a=articles[key]||articles.about;return `${nav()}<main class="docs-layout" id="main"><aside class="docs-sidebar"><h4>The basics</h4>${Object.entries(articles).map(([k,v])=>`<a class="${key===k?'active':''}" href="/#/docs/${k}">${v[0]}</a>`).join('')}</aside><article class="docs-main"><div class="eyebrow">LIVEBEAM DOCUMENTATION</div><h1>${a[0]}</h1><p>${a[1]}</p><h2>${a[2]}</h2><p>${a[3]}</p>${key==='connections'?'<pre>cp .env.example .env\n# Fill in your service credentials\nnpm start</pre>':''}<div class="notice" style="margin-top:35px">Need to try it first? <a class="muted-link" href="/#/dashboard">Open the demo dashboard →</a></div></article></main>${footer()}`}
function connect(){return `${nav()}<main class="content" id="main" style="max-width:760px;text-align:center"><div class="eyebrow">LET’S GET CONNECTED</div><h1 style="font-size:38px">Welcome to Livebeam.</h1><p class="subtle">Connect your Discord account to manage a real server, or take the dashboard for a spin with a private browser demo.</p><div class="panel"><h2>Connect your community</h2><p>Live connections require the included server and your own Discord application credentials.</p><button class="purple" data-action="login">Connect Discord</button> <button class="outline" data-action="invite">Add bot to Discord</button><p><a class="muted-link" href="/#/docs/connections">Read the setup guide →</a></p></div><a class="btn secondary" href="/#/dashboard">Explore demo dashboard</a></main>${footer()}`}
function misc(page){const text={support:['How can we help?','Start with the setup guides or review the feature notes below. This personal edition does not have a staffed support server.','<a class="btn purple" href="/#/docs">Open documentation</a> <a class="btn outline" href="https://github.com/mikeklwong/livebeam/issues" target="_blank" rel="noopener">Project issues ↗</a>'],branding:['Made for your community.','Use the Livebeam mark in your own project. Keep it legible and give it room to breathe.','<div class="panel" style="text-align:center;font-size:50px">ϟ Livebeam</div><a class="btn purple" download="livebeam-logo.svg" href="/logo.svg">Download SVG logo</a>'],partners:['Grow together.','This personal project does not currently operate a partner program. You can still configure creator notifications for your community.','<a class="btn purple" href="/#/dashboard">Manage creators</a>'],languages:['A shared language.','The current interface is available in English. Additional translations have not been implemented.','<a class="btn outline" href="https://github.com/mikeklwong/livebeam/issues" target="_blank" rel="noopener">Suggest a translation ↗</a>'],terms:['Personal project terms','Livebeam is provided for personal experimentation without a service-level guarantee. You are responsible for the accounts and Discord servers you connect, and for complying with each connected platform’s terms.','<p>Do not use this project to spam, impersonate others, or access servers without permission. Review and adapt these project notes before offering a public service. No subscription purchase is available here.</p>'],privacy:['Privacy at Livebeam','The hosted demo stores configuration in your browser’s local storage. It does not connect to Discord or upload demo settings to a backend.','<p>The self-hosted service stores server configuration and delivery state on your server. OAuth sessions are held in server memory and a secure session cookie identifies your browser. Third-party API requests are made only by your configured service. The interface loads the Inter font from Google Fonts. Export or reset demo data from Settings.</p>']};if(page==='faq')return `${nav()}<main id="main" class="content" style="max-width:850px"><h1>Frequently asked questions</h1>${[['Does the demo send real notifications?','No. It lets you save and edit sample settings in this browser. Run the included service and connect Discord to send real messages.'],['What credentials do I need?','A Discord application and bot token. Add Twitch credentials, a YouTube API key, and a Kick access token for the providers you use.'],['Is Pro a paid subscription?','Billing is not enabled in the personal edition. All implemented tools are available without a purchase.'],['Why isn’t my live role updating?','Check the member mapping, role hierarchy, Manage Roles permission, and the provider credentials. Review the event log for provider errors.'],['Does it run on GitHub Pages?','The demo frontend can be served as static files. Real OAuth, polling, role updates, and delivery require the included always-on Node server.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</main>${footer()}`;if(page==='status')return `${nav()}<main id="main" class="content" style="max-width:850px"><h1>Service status</h1><p class="subtle">Configuration status for this deployment. This is not an uptime monitor.</p><div id="service-status" class="status-list"><div class="status-row">Web interface <span class="badge">Available</span></div><div class="status-row">Live service <span class="badge paused">Checking…</span></div></div></main>${footer()}`;const [title,desc,body]=text[page]||['Page not found','This page does not exist.','<a href="/#/" class="btn purple">Back home</a>'];return `${nav()}<main id="main" class="content" style="max-width:850px"><h1>${title}</h1><p class="subtle">${desc}</p>${body}</main>${footer()}`}
const navigation=[['overview','⌂','Overview'],['notifications','◉','Notifications'],['roles','♙','Live Role'],['schedules','▦','Schedules'],['logs','≡','Event log'],['settings','⚙','Settings']];
function dash(section='overview'){return `<div class="dash"><header class="dash-top">${brand()}<div class="account"><a href="/#/docs" class="subtle">Documentation ↗</a><span class="account-avatar">${esc((session?.user?.username||'D')[0].toUpperCase())}</span><span>${esc(session?.user?.username||'Demo account')}</span><button class="text-button" data-action="${mode==='live'?'logout':'login'}">${mode==='live'?'Log out':'Connect Discord'}</button></div></header><div class="dash-layout"><aside class="dash-sidebar"><select class="server-select" aria-label="Select server" id="guild-select">${mode==='live'?(session?.guilds||[]).map(g=>`<option value="${esc(g.id)}" ${guild===g.id?'selected':''}>${esc(g.name)}</option>`).join(''):`<option>${esc(state.settings.serverName)}</option>`}</select><div class="label">YOUR SERVER</div>${navigation.map(([key,icon,label])=>`<a class="${section===key?'active':''}" href="/#/dashboard/${key}"><span class="nav-symbol">${icon}</span>${label}</a>`).join('')}<div class="label">MORE FROM LIVEBEAM</div><a href="/#/pro"><span class="nav-symbol">✧</span>Explore Pro</a><a href="/#/support"><span class="nav-symbol">?</span>Help & support</a><a href="/#/"><span class="nav-symbol">↗</span>Back to website</a></aside><main id="main" class="dash-main"><div class="breadcrumbs">${esc(mode==='demo'?state.settings.serverName:session?.guilds?.find(g=>g.id===guild)?.name||'Server')} &nbsp; / &nbsp; ${navigation.find(x=>x[0]===section)?.[2]||'Overview'}</div>${mode==='demo'?'<div class="notice">You’re exploring demo mode. Changes are saved in this browser; no Discord messages are sent. <a class="muted-link" href="/#/connect">Connect your server →</a></div>':''}${dashboardBody(section)}</main></div></div>`}
function heading(title,desc,action='',label=''){return `<div class="dash-heading"><div><h1>${title}</h1><p>${desc}</p></div>${action?`<button class="btn purple" data-action="${action}">＋ ${label}</button>`:''}</div>`}
function dashboardBody(s){if(s==='notifications')return `${heading('Stream notifications','A little heads-up for every go-live moment.','new-notification','Add notification')}<div class="tabs" role="tablist">${['all','twitch','youtube','kick'].map(p=>`<button role="tab" aria-selected="${platform===p}" class="${platform===p?'active':''}" data-platform="${p}">${p==='all'?'All platforms':p[0].toUpperCase()+p.slice(1)} <span class="subtle">${state.notifications.filter(n=>p==='all'||n.platform===p).length}</span></button>`).join('')}</div><input class="search" id="search-notifications" type="search" aria-label="Search creators" placeholder="Search creators…"><div class="panel" style="padding:0"><div class="table-wrap" id="notification-table">${notificationTable()}</div></div><p class="subtle" style="font-size:12px">Make it your own with variables, custom colors, and stream-end rules. <a class="muted-link" href="/#/docs/notifications">Read the guide ↗</a></p>`;
if(s==='roles')return `${heading('Live Role','Give creators their moment in the spotlight.','new-role','Add configuration')}<div class="panel">${state.roles.length?state.roles.map(r=>`<div class="schedule-card"><div class="platform-icon">♙</div><div class="schedule-info"><h3>${esc(r.name)}</h3><p>Role: ${esc(r.roleId)} · ${r.filterMode==='exclude'?'Exclude':'Include'} filter · ${esc(r.members.split('\n').filter(Boolean).length)} mapped creators</p></div><button class="text-button" data-edit-role="${r.id}">Edit</button><button class="text-button danger" data-delete="roles:${r.id}">Delete</button></div>`).join(''):empty('Your creators belong in the spotlight','Add a Live Role configuration to get started.','new-role','Add configuration')}</div><div class="notice">The bot needs Manage Roles, and its highest role must sit above the role you choose. <a class="muted-link" href="/#/docs/roles">Setup guide →</a></div>`;
if(s==='schedules')return `${heading('Stream schedules','Make your next stream part of their plans.','new-schedule','Add schedule')}<div class="panel">${state.schedules.length?state.schedules.map(r=>`<div class="schedule-card"><div class="schedule-date">TWITCH<strong>▦</strong></div><div class="schedule-info"><h3>${esc(r.title)}</h3><p>${esc(r.creator)} · ${mode==='demo'?'Demo configuration':'Automatic sync'}</p></div><button class="text-button" data-edit-schedule="${r.id}">Edit</button><button class="text-button danger" data-delete="schedules:${r.id}">Delete</button></div>`).join(''):empty('Your calendar is a blank canvas','Connect a Twitch schedule to create community events.','new-schedule','Add schedule')}</div>`;
if(s==='logs')return `${heading('Event log','A record of configuration changes and delivery activity.')}<div class="panel">${logs()}</div>`;
if(s==='settings')return `${heading('Server settings','Your community, your preferences.')}<form id="settings-form" class="panel"><h2>General</h2><div class="form-grid"><label class="field">Community name<input name="serverName" maxlength="80" required value="${esc(state.settings.serverName)}"></label><label class="field">Manager role IDs<input name="managerRoles" value="${esc(state.settings.managerRoles)}" placeholder="Comma-separated Discord role IDs"><small>Members with these roles may manage Livebeam settings.</small></label></div><div class="form-actions"><button class="purple" type="submit">Save settings</button></div></form><div class="panel"><h2>Your data</h2><p class="subtle" style="font-size:13px">Download a backup or restore a configuration file. Exports include settings, creator identifiers, and role mappings.</p><button class="outline small" data-action="export">Export JSON</button> <button class="outline small" data-action="import">Import JSON</button><input class="file-input" id="import-file" type="file" accept="application/json">${mode==='demo'?'<button class="text-button danger" data-action="reset">Reset demo data</button>':''}</div><div class="panel"><h2>Connection diagnostics</h2><div id="diagnostics"><p class="subtle">${mode==='demo'?'Demo mode is active. No provider credentials are used.':'Loading provider status…'}</p></div></div>`;
return `${heading('Welcome to your community 👋','A home for your creators. A place for your next big moment.')}<div class="stats"><div class="stat"><small>Stream notifications</small><strong>${state.notifications.length}</strong><span>${state.notifications.filter(n=>n.enabled).length} enabled</span></div><div class="stat"><small>Live Role configurations</small><strong>${state.roles.length}</strong><span>Creator spotlight</span></div><div class="stat"><small>Connected schedules</small><strong>${state.schedules.length}</strong><span>Community calendar</span></div></div><div class="split"><div class="panel"><h2>Let’s get your community ready</h2><p class="subtle" style="font-size:13px">Add a creator, choose a channel, and make your next stream impossible to miss.</p><a class="btn purple small" href="/#/dashboard/notifications">Manage notifications →</a><p><a class="muted-link" style="font-size:12px" href="/#/docs">Read the getting started guide ↗</a></p></div><div class="panel"><h2>Made for your server</h2><p class="subtle" style="font-size:13px">Explore custom embeds, live roles, and schedules. All implemented tools are available in this personal edition.</p><a class="btn outline small" href="/#/pro">Explore the features</a></div></div><div class="panel"><h2>Recent activity</h2>${logs(5)}</div>${mode==='demo'&&!state.notifications.length?'<button class="outline small" data-action="samples">Load sample configurations</button>':''}`}
function empty(title,desc,action,label){return `<div class="empty"><div style="font-size:35px;color:#a882df">◉</div><h3>${title}</h3><p>${desc}</p>${action?`<button class="purple small" data-action="${action}">${label}</button>`:''}</div>`}
function logs(limit=100){return state.logs.slice(0,limit).map(l=>`<div class="log"><div>${esc(l.message)}</div><span>${esc(new Date(l.time).toLocaleString())}</span></div>`).join('')||empty('All quiet here','Your activity will appear here.');}
function notificationTable(search=''){const list=state.notifications.filter(n=>(platform==='all'||n.platform===platform)&&n.creator.toLowerCase().includes(search.toLowerCase()));return list.length?`<table class="data-table"><thead><tr><th>Creator</th><th>Discord channel</th><th>Status</th><th>Actions</th></tr></thead><tbody>${list.map(n=>`<tr><td><div class="channel-name"><span class="platform-icon ${n.platform}">${n.platform==='youtube'?'▶':n.platform==='kick'?'K':'◉'}</span><div>${esc(n.creator)}<div class="subtle" style="font-size:10px;margin-top:5px;font-weight:400">${esc(n.platform)}</div></div></div></td><td><span class="subtle">#</span> ${esc(metadata.channels.find(c=>c.id===n.channel)?.name||n.channel)}</td><td><button class="badge ${n.enabled?'':'paused'}" data-toggle="${n.id}">${n.enabled?'Enabled':'Paused'}</button></td><td><div class="actions"><button class="text-button" data-edit-notification="${n.id}">Edit</button><button class="text-button" data-preview="${n.id}">Preview</button><button class="text-button danger" data-delete="notifications:${n.id}">Delete</button></div></td></tr>`).join('')}</tbody></table>`:empty('No notifications yet',search?'No creators match your search.':'Add your first creator to get the conversation started.','new-notification','Add notification')}
function field(label,name,value='',extra='',type='text'){return `<label class="field">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`}
function select(label,name,items,value){return `<label class="field">${label}<select name="${name}">${items.map(i=>{const [v,t]=Array.isArray(i)?i:[i,i];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`}).join('')}</select></label>`}
function openModal(title,body){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button data-action="close" aria-label="Close dialog">×</button></div>${body}`;modal.showModal()}
const formEnd='<p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="outline" data-action="close">Cancel</button><button type="submit" class="purple">Save configuration</button></div></form>';
function editNotification(id){const n=state.notifications.find(n=>n.id===id)||{id:uid(),platform:'twitch',creator:'',channel:'',message:'{name} is live! Come hang out: {url}',color:'#9146ff',cooldown:0,cleanup:'keep',enabled:true,videoType:'both'};openModal(id?'Edit notification':'Add notification',`<form id="notification-form" data-id="${n.id}"><div class="form-grid">${select('Platform','platform',['twitch','youtube','kick'],n.platform)}${field('Creator login or channel ID','creator',n.creator,'required maxlength="100" placeholder="e.g. cozyplayer"')}${mode==='live'?select('Discord channel','channel',metadata.channels.map(c=>[c.id,'# '+c.name]),n.channel):field('Discord channel','channel',n.channel,'required placeholder="stream-announcements" maxlength="100"')}${select('YouTube content','videoType',[['both','Uploads and livestreams'],['uploads','Uploads'],['live','Livestreams']],n.videoType)}<label class="field full">Announcement message<textarea name="message" required maxlength="1800">${esc(n.message)}</textarea><small>Variables: {name}, {title}, {game}, {url}. Live messages disable mentions.</small></label>${field('Embed color','color',n.color,'','color')}${field('Cooldown (minutes)','cooldown',n.cooldown,'min="0" max="10080" required','number')}</div><details><summary>Advanced options</summary><div class="form-grid" style="margin-top:20px">${field('Game filter (comma-separated)','games',n.games,'maxlength="300"')}${field('Title keywords (all must match)','keywords',n.keywords,'maxlength="300"')}${select('When the stream ends','cleanup',[['keep','Keep announcement'],['edit','Edit announcement'],['delete','Delete announcement'],['message','Send ending message']],n.cleanup)}${field('Ending message','endMessage',n.endMessage||'{name} has finished streaming.','maxlength="1800"')}${field('Thumbnail URL (HTTPS)','thumbnail',n.thumbnail,'placeholder="https://…"','url')}${field('Custom bot display name','botName',n.botName,'maxlength="80"')}${field('Custom bot avatar URL (HTTPS)','botAvatar',n.botAvatar,'placeholder="https://…"','url')}<label class="field">Discord webhook environment key<input name="webhookKey" value="${esc(n.webhookKey)}" placeholder="COMMUNITY_WEBHOOK" pattern="[A-Z][A-Z0-9_]*"><small>Set the webhook URL in the server environment. Never paste a webhook secret here.</small></label></div><label class="check-field"><input name="crosspost" type="checkbox" ${n.crosspost?'checked':''}>Automatically publish to following servers</label></details><label class="check-field"><input name="enabled" type="checkbox" ${n.enabled?'checked':''}>Enable this notification</label><div class="preview-label">MESSAGE PREVIEW · ILLUSTRATIVE CONTENT</div><div id="live-preview" class="inline-preview">${preview(n)}</div>${formEnd}`)}
function editRole(id){const r=state.roles.find(r=>r.id===id)||{id:uid(),name:'Live on Twitch',roleId:'',filterMode:'include',filterRoles:'',members:'',channel:'',message:'{name} is now streaming! {url}'};openModal(id?'Edit Live Role':'Add Live Role',`<form id="role-form" data-id="${r.id}"><div class="form-grid">${field('Configuration name','name',r.name,'required maxlength="80"')}${mode==='live'?select('Live role','roleId',metadata.roles.filter(x=>!x.managed&&x.id!==guild).map(x=>[x.id,x.name]),r.roleId):field('Live role name or ID','roleId',r.roleId,'required')}${select('Filter mode','filterMode',[['include','Include matching roles'],['exclude','Exclude matching roles']],r.filterMode)}${field('Filter role IDs (comma-separated)','filterRoles',r.filterRoles)}<label class="field full">Member mappings<textarea required name="members" placeholder="123456789012345678:cozyplayer">${esc(r.members)}</textarea><small>One DiscordUserID:twitchlogin per line. Explicit mappings are required.</small></label>${field('Announcement channel ID (optional)','channel',r.channel)}${field('Announcement message','message',r.message,'maxlength="1800"')}</div>${formEnd}`)}
function editSchedule(id){const r=state.schedules.find(r=>r.id===id)||{id:uid(),creator:'',title:'{title}',description:'Join {name} live on Twitch! {url}'};openModal(id?'Edit schedule':'Add schedule',`<form id="schedule-form" data-id="${r.id}"><div class="form-grid">${field('Twitch login','creator',r.creator,'required pattern="[A-Za-z0-9_]+" maxlength="100"')}${field('Event title','title',r.title,'required maxlength="100"')}<label class="field full">Event description<textarea name="description" required maxlength="1000">${esc(r.description)}</textarea><small>Variables: {name}, {title}, {url}</small></label></div><p class="notice">${mode==='demo'?'This saves a demo configuration. No Discord events will be created.':'Upcoming streams will sync on the next polling cycle.'}</p>${formEnd}`)}
function upsert(collection,record){const i=state[collection].findIndex(r=>r.id===record.id);if(i<0)state[collection].push(record);else state[collection][i]=record}
async function mutate(fn){const before=structuredClone(state);try{fn();await save();return true}catch(e){state=before;toast(e.message);return false}}
document.addEventListener('submit',async e=>{if(!['notification-form','role-form','schedule-form','settings-form'].includes(e.target.id))return;e.preventDefault();const form=e.target;const data=Object.fromEntries(new FormData(form));if(form.id==='settings-form'){if(await mutate(()=>{state.settings=data;log('Updated server settings')})){toast('Settings saved');render()}return}let collection=form.id==='notification-form'?'notifications':form.id==='role-form'?'roles':'schedules';if(collection==='notifications'){data.enabled=form.elements.enabled.checked;data.crosspost=form.elements.crosspost.checked;data.cooldown=Number(data.cooldown);if((data.thumbnail&&!data.thumbnail.startsWith('https://'))||(data.botAvatar&&!data.botAvatar.startsWith('https://'))){form.querySelector('.form-error').textContent='Image URLs must use HTTPS.';return}}if(collection==='roles'&&!data.members.trim().split('\n').every(line=>/^\d{17,20}:[a-zA-Z0-9_]+$/.test(line.trim()))){form.querySelector('.form-error').textContent='Use DiscordUserID:twitchlogin, one per line. Discord IDs have 17–20 digits.';return}if(await mutate(()=>{upsert(collection,{...data,id:form.dataset.id});log(`Saved ${collection==='notifications'?'notification for '+data.creator:collection==='roles'?'Live Role '+data.name:'schedule for '+data.creator}`)})){modal.close();toast('Configuration saved');render()}});
document.addEventListener('input',e=>{if(e.target.id==='search-notifications')$('#notification-table').innerHTML=notificationTable(e.target.value);if(e.target.closest('#notification-form')){const f=$('#notification-form');$('#live-preview').innerHTML=preview(Object.fromEntries(new FormData(f)))}});
document.addEventListener('change',async e=>{if(e.target.id==='guild-select'){guild=e.target.value;await loadGuild();render()}if(e.target.id==='import-file'&&e.target.files[0]){try{if(e.target.files[0].size>2000000)throw Error('File is too large. Maximum 2 MB.');const incoming=JSON.parse(await e.target.files[0].text());validateImport(incoming);openModal('Restore configuration?',`<p>This replaces your current configuration with ${incoming.notifications.length} notifications, ${incoming.roles.length} role rules, and ${incoming.schedules.length} schedules.</p><div class="form-actions"><button class="outline" data-action="close">Cancel</button><button class="purple" id="confirm-import">Restore configuration</button></div>`);$('#confirm-import').onclick=async()=>{if(await mutate(()=>{state=incoming;log('Restored configuration backup')})){modal.close();toast('Configuration restored');render()}}}catch(err){toast(err.message)}}});
function validateImport(s){if(!s||typeof s!=='object'||!s.settings||typeof s.settings.serverName!=='string'||typeof s.settings.managerRoles!=='string')throw Error('Invalid Livebeam backup.');for(const k of ['notifications','roles','schedules','logs'])if(!Array.isArray(s[k])||s[k].length>1000)throw Error('Invalid backup collection.');const ids=new Set();for(const r of [...s.notifications,...s.roles,...s.schedules]){if(typeof r.id!=='string'||!/^[a-zA-Z0-9-]{1,80}$/.test(r.id)||ids.has(r.id))throw Error('Invalid or duplicate record ID.');ids.add(r.id)}for(const n of s.notifications)if(!['twitch','youtube','kick'].includes(n.platform)||typeof n.creator!=='string'||typeof n.channel!=='string'||typeof n.message!=='string'||!Number.isFinite(n.cooldown))throw Error('Invalid notification.');for(const r of s.roles)if(typeof r.name!=='string'||typeof r.members!=='string'||typeof r.roleId!=='string')throw Error('Invalid role rule.');for(const r of s.schedules)if(typeof r.creator!=='string'||typeof r.title!=='string'||typeof r.description!=='string')throw Error('Invalid schedule.');for(const l of s.logs)if(typeof l.message!=='string'||!Number.isFinite(Date.parse(l.time)))throw Error('Invalid log.');}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-action]');if(!b)return;try{if(b.dataset.platform){platform=b.dataset.platform;render();return}if(b.dataset.editNotification)return editNotification(b.dataset.editNotification);if(b.dataset.editRole)return editRole(b.dataset.editRole);if(b.dataset.editSchedule)return editSchedule(b.dataset.editSchedule);if(b.dataset.preview){openModal('Notification preview',`<p class="subtle">Illustrative preview. This does not send a message.</p>${preview(state.notifications.find(n=>n.id===b.dataset.preview))}`);return}if(b.dataset.toggle){if(await mutate(()=>{const n=state.notifications.find(n=>n.id===b.dataset.toggle);n.enabled=!n.enabled;log(`${n.enabled?'Enabled':'Paused'} notification for ${n.creator}`)}))render();return}if(b.dataset.delete){const [collection,id]=b.dataset.delete.split(':');openModal('Delete configuration?',`<p>This removes the saved rule. Existing Discord messages and events are retained.</p><div class="form-actions"><button class="outline" data-action="close">Cancel</button><button class="purple" id="confirm-delete">Delete configuration</button></div>`);$('#confirm-delete').onclick=async()=>{if(await mutate(()=>{state[collection]=state[collection].filter(r=>r.id!==id);log('Deleted a configuration')})){modal.close();render();toast('Configuration deleted')}};return}switch(b.dataset.action){case'menu':{let m=$('.menu');m.hidden=!m.hidden;b.setAttribute('aria-expanded',!m.hidden);break}case'close':modal.close();break;case'new-notification':editNotification();break;case'new-role':editRole();break;case'new-schedule':editSchedule();break;case'login':{const r=await api('/api/connect');location.href=r.url;break}case'invite':{const r=await api('/api/invite');location.href=r.url;break}case'logout':await api('/api/logout',{method:'POST',body:'{}'});session=null;mode='demo';state={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'{}')};render();break;case'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='livebeam-config.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Configuration exported');break}case'import':$('#import-file').click();break;case'reset':openModal('Reset demo data?',`<p>This removes the demo settings saved in this browser. Export a backup first if you want to keep them.</p><div class="form-actions"><button class="outline" data-action="close">Cancel</button><button class="purple" id="confirm-reset">Reset demo</button></div>`);$('#confirm-reset').onclick=async()=>{if(await mutate(()=>{state=fresh()})){modal.close();render();toast('Demo reset')}};break;case'samples':if(await mutate(()=>{state.notifications=[['cozyplayer','twitch'],['Moonlight Studio','youtube'],['nightowl','kick']].map(([creator,platform])=>({id:uid(),creator,platform,channel:'stream-announcements',message:'{name} is live! Come hang out: {url}',color:'#9146ff',cooldown:15,cleanup:'edit',enabled:true,videoType:'both'}));log('Loaded illustrative sample configurations')}))render();break}}catch(err){toast(err.message)}});
async function loadGuild(){try{const [config,meta]=await Promise.all([api(`/api/guilds/${guild}/config`),api(`/api/guilds/${guild}/metadata`)]);state=config;metadata=meta}catch(e){toast(e.message);throw e}}
function render(){const parts=(location.hash.slice(1)||'/').split('/').filter(Boolean);const page=parts[0]||'home';app.innerHTML=page==='home'?home():page==='dashboard'?dash(parts[1]):page==='pro'?pro():page==='docs'?docs(parts[1]):page==='connect'?connect():misc(page);document.title=`${page==='home'?'Your streaming community on Discord':page==='dashboard'?'Dashboard':page[0].toUpperCase()+page.slice(1)} | Livebeam`;if(page==='status'||(page==='dashboard'&&parts[1]==='settings'&&mode==='live')){api('/api/health').then(h=>{const target=$('#service-status')||$('#diagnostics');if(target)target.innerHTML=Object.entries(h.services).map(([k,v])=>`<div class="status-row">${esc(k)}<span class="badge ${v?'':'paused'}">${v?'Configured':'Not configured'}</span></div>`).join('')}).catch(()=>{if($('#service-status'))$('#service-status').innerHTML='<div class="status-row">Web interface <span class="badge">Available</span></div><div class="status-row">Live service <span class="badge paused">Demo only</span></div>'})}}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
try{session=await api('/api/session');if(session.user&&session.guilds.length){mode='live';guild=session.guilds[0].id;await loadGuild();render()}}catch{session=null;mode='demo'}
